`GalleryIndex` stores gallery entries without any filesystem or network access. Entry IDs must be non-negative integers; names must contain non-whitespace; duplicate IDs are rejected with `Error`. The constructor and `replace` must snapshot every entry object so later caller mutations cannot affect stored state. Validation failure in `replace` must leave the previous state unchanged. `list` returns fresh entry objects ordered by ascending numeric ID. An empty collection is valid.

Known-bad source:

```typescript
export interface GalleryEntry {
  id: number;
  name: string;
  note: string;
}

function validateEntries(entries: readonly GalleryEntry[]): void {
  const ids = new Set<number>();
  for (const entry of entries) {
    if (!Number.isInteger(entry.id) || entry.id < 0) throw new Error("invalid id");
    if (entry.name.trim().length === 0) throw new Error("invalid name");
    if (ids.has(entry.id)) throw new Error("duplicate id");
    ids.add(entry.id);
  }
}

export class GalleryIndex {
  private entries: GalleryEntry[];

  constructor(entries: readonly GalleryEntry[] = []) {
    validateEntries(entries);
    this.entries = entries.map((entry) => ({ ...entry }));
  }

  replace(entries: readonly GalleryEntry[]): void {
    validateEntries(entries);
    this.entries = entries.slice();
  }

  list(): GalleryEntry[] {
    return this.entries
      .map((entry) => ({ ...entry }))
      .sort((a, b) => a.id - b.id);
  }
}
```

