import { GalleryEntry, GalleryIndex } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(fn: () => unknown, message: string): void {
  let didThrow = false;
  try { fn(); } catch (error) { didThrow = error instanceof Error; }
  assert(didThrow, message);
}

const empty = new GalleryIndex();
equal(empty.list().length, 0, "empty collection is valid");

const source: GalleryEntry[] = [
  { id: 7, name: "Seven", note: "later" },
  { id: 0, name: " Zero ", note: "first" },
  { id: 3, name: "Three", note: "middle" }
];
const index = new GalleryIndex(source);
source[0].name = "Mutated";
source[0].note = "changed";
source.push({ id: 9, name: "Nine", note: "new" });
let listed = index.list();
equal(listed.map(entry => entry.id).join(","), "0,3,7", "list sorts IDs numerically ascending");
equal(listed[2].name, "Seven", "constructor snapshots entries");
equal(listed[2].note, "later", "constructor retains copied note");
listed[0].name = "Changed through list";
listed.reverse();
equal(index.list().map(entry => entry.name).join("|"), " Zero |Three|Seven", "list returns fresh objects and array");

const replacement: GalleryEntry[] = [{ id: 2, name: "Two", note: "replacement" }, { id: 1, name: "One", note: "replacement" }];
index.replace(replacement);
replacement[0].name = "Mutated replacement";
replacement[0].note = "mutated note";
equal(index.list().map(entry => entry.name).join("|"), "One|Two", "replace snapshots every entry object");

const beforeFailure = index.list();
throws(() => index.replace([{ id: 4, name: "Four", note: "x" }, { id: 4, name: "Duplicate", note: "y" }]), "replace rejects duplicate IDs");
equal(JSON.stringify(index.list()), JSON.stringify(beforeFailure), "failed replace leaves state unchanged");
throws(() => index.replace([{ id: -1, name: "Bad", note: "" }]), "negative ID is rejected");
equal(JSON.stringify(index.list()), JSON.stringify(beforeFailure), "negative-ID failure is atomic");
throws(() => new GalleryIndex([{ id: 1.5, name: "Bad", note: "" }]), "fractional ID is rejected");
throws(() => new GalleryIndex([{ id: NaN, name: "Bad", note: "" }]), "NaN ID is rejected");
throws(() => new GalleryIndex([{ id: 1, name: " \t\n", note: "anything" }]), "blank name is rejected");
throws(() => new GalleryIndex([{ id: 1, name: "A", note: "" }, { id: 1, name: "B", note: "" }]), "constructor rejects duplicate IDs");

index.replace([]);
equal(index.list().length, 0, "replace accepts an empty collection");

